import{bQ as e,aL as a,u as r,G as o}from"./chunks/framework.C1gZXFVa.js";const c=JSON.parse('{"title":"开仓主流程","description":"平台永续限价开仓：用户经网关进合约委托，校验后调撮合占用保证金并进簿；行情异步推送。","frontmatter":{"title":"开仓主流程","description":"平台永续限价开仓：用户经网关进合约委托，校验后调撮合占用保证金并进簿；行情异步推送。","head":[["meta",{"name":"keywords","content":"开源交易所,交易所开源,交易所源码,开源交易所源码,商业源码,交易所商业源码,数字货币交易所,加密货币交易所,虚拟货币交易所,区块链交易所,撮合引擎,开发撮合引擎,开源撮合引擎,订单簿,现货交易,现货交易所,合约交易,永续合约,合约交易所,期权交易,加密期权,开源OTC,OTC交易,场外交易,法币交易,区块链钱包,数字货币钱包,充值提现,多商户交易所,交易所架构,交易所设计,交易系统设计,资金清算,资产账务,风控系统,行情推送,WebSocket行情,TGEX"}],["link",{"rel":"canonical","href":"https://tgex.net/pages/080501"}],["meta",{"property":"og:url","content":"https://tgex.net/pages/080501"}],["meta",{"property":"og:title","content":"开仓主流程 · TGEX"}],["meta",{"property":"og:description","content":"平台永续限价开仓：用户经网关进合约委托，校验后调撮合占用保证金并进簿；行情异步推送。"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://tgex.net/og.jpg"}],["meta",{"name":"twitter:title","content":"开仓主流程 · TGEX"}],["meta",{"name":"twitter:description","content":"平台永续限价开仓：用户经网关进合约委托，校验后调撮合占用保证金并进簿；行情异步推送。"}],["meta",{"name":"twitter:image","content":"https://tgex.net/og.jpg"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"TechArticle\\",\\"headline\\":\\"开仓主流程\\",\\"description\\":\\"平台永续限价开仓：用户经网关进合约委托，校验后调撮合占用保证金并进簿；行情异步推送。\\",\\"keywords\\":\\"开源交易所,交易所开源,交易所源码,开源交易所源码,商业源码,交易所商业源码,数字货币交易所,加密货币交易所,虚拟货币交易所,区块链交易所,撮合引擎,开发撮合引擎,开源撮合引擎,订单簿,现货交易,现货交易所,合约交易,永续合约,合约交易所,期权交易,加密期权,开源OTC,OTC交易,场外交易,法币交易,区块链钱包,数字货币钱包,充值提现,多商户交易所,交易所架构,交易所设计,交易系统设计,资金清算,资产账务,风控系统,行情推送,WebSocket行情,TGEX\\",\\"url\\":\\"https://tgex.net/pages/080501\\",\\"mainEntityOfPage\\":\\"https://tgex.net/pages/080501\\",\\"inLanguage\\":\\"zh-CN\\",\\"isPartOf\\":{\\"@type\\":\\"WebSite\\",\\"name\\":\\"TGEX\\",\\"url\\":\\"https://tgex.net/\\"},\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"TGEX\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"TGEX\\",\\"logo\\":{\\"@type\\":\\"ImageObject\\",\\"url\\":\\"https://tgex.net/logo.svg\\"}},\\"image\\":\\"https://tgex.net/og.jpg\\"}"]]},"headers":[],"relativePath":"pages/080501.md","filePath":"08.合约手册/05.核心流程/01.开仓主流程.md"}'),n={name:"pages/080501.md"};function i(d,t,l,p,s,h){return a(),r("div",null,[...t[0]||(t[0]=[o('<div class="doc-eyebrow">合约手册 · 核心交易流程 / TGEX KNOWLEDGE BASE</div><h1 id="开仓主流程" tabindex="-1">开仓主流程 <a class="header-anchor" href="#开仓主流程" aria-label="Permalink to &quot;开仓主流程&quot;">​</a></h1><div class="doc-lead">平台永续限价开仓沿时序：用户 / 机器人 → 应用网关 → 合约委托 → 合约撮合；同步返回委托编号（已受理 ≠ 已全部成交）。深度与成交由撮合异步交给行情推送。</div><p>本文假定服务已起来、合约产品已可交易；以 <strong>开多 / 开空 · 限价</strong> 为主路径。进簿后的比价与持仓增量在撮合内完成；展示见<a href="/pages/080504">行情推送流程</a>。统一数字见<a href="/pages/0801#complete">业务概述 · 案例</a>。</p><h2 id="_1-用户-机器人-→-应用网关" tabindex="-1">1. 用户 / 机器人 → 应用网关 <a class="header-anchor" href="#_1-用户-机器人-→-应用网关" aria-label="Permalink to &quot;1. 用户 / 机器人 → 应用网关&quot;">​</a></h2><p>调用方提交开仓：合约产品、开多或开空、价格、数量、杠杆 / 保证金模式、来源等。经应用网关进入合约委托。</p><h2 id="_2-应用网关-→-合约委托" tabindex="-1">2. 应用网关 → 合约委托 <a class="header-anchor" href="#_2-应用网关-→-合约委托" aria-label="Permalink to &quot;2. 应用网关 → 合约委托&quot;">​</a></h2><p>网关转发与接入；鉴权细节不在本文展开。请求进入委托同步受理段。</p><h2 id="_3-委托-校验" tabindex="-1">3. 委托：校验 <a class="header-anchor" href="#_3-委托-校验" aria-label="Permalink to &quot;3. 委托：校验&quot;">​</a></h2><p>调撮合「下单」之前，委托侧完成本地 / 配置校验。任一步失败则拒单，<strong>不调撮合、不占用保证金</strong>：</p><ol><li>入参完整性（限价须有合法正价格与数量）</li><li>用户可交易状态</li><li>合约产品：存在、启用、涨跌幅、交易时段等</li><li>杠杆与仓位限额（含杠杆档最大可开）</li><li>可用保证金是否可能覆盖占用（预检口径）</li><li>客户端订单号幂等等防重（若启用）</li></ol><h2 id="_4-委托-→-撮合-开仓" tabindex="-1">4. 委托 → 撮合：开仓 <a class="header-anchor" href="#_4-委托-→-撮合-开仓" aria-label="Permalink to &quot;4. 委托 → 撮合：开仓&quot;">​</a></h2><p>校验通过后，委托同步调用撮合开仓。撮合侧在事件链上：</p><ol><li>按规则从合约账户热钱包占用保证金（可用 → 占用）</li><li>建立委托热数据并进入订单簿处理</li><li>若立即与对手成交：增加或加仓持仓、重算均价与占用；剩余量挂簿或结束</li></ol><p>预检够、受理瞬间不够时，以撮合串行结果为准——预检不占最终坑。</p><h2 id="_5-同步返回调用方" tabindex="-1">5. 同步返回调用方 <a class="header-anchor" href="#_5-同步返回调用方" aria-label="Permalink to &quot;5. 同步返回调用方&quot;">​</a></h2><table tabindex="0"><thead><tr><th>结果</th><th>含义</th></tr></thead><tbody><tr><td>成功 + 委托编号</td><td>已受理：保证金按规则占用，委托已进入撮合处理链</td></tr><tr><td>校验 / 预检失败</td><td>未调撮合或未占用</td></tr><tr><td>撮合拒绝</td><td>通常无成功占用</td></tr><tr><td>调撮合超时</td><td><strong>可能已占用</strong>：先查委托 / 持仓终态，禁止未知时再发一笔新开仓</td></tr></tbody></table><p>持仓明细与全部成交结果不在同步回包里保证带齐；以查询与推送为准。</p><h2 id="_6-异步旁路-撮合-→-行情" tabindex="-1">6. 异步旁路：撮合 → 行情 <a class="header-anchor" href="#_6-异步旁路-撮合-→-行情" aria-label="Permalink to &quot;6. 异步旁路：撮合 → 行情&quot;">​</a></h2><p>深度 / 成交经消息交给行情，推盘口与成交展示。推送<strong>不改</strong>持仓与保证金权威结果。见<a href="/pages/080504">行情推送流程</a>。</p><h2 id="本文边界" tabindex="-1">本文边界 <a class="header-anchor" href="#本文边界" aria-label="Permalink to &quot;本文边界&quot;">​</a></h2><table tabindex="0"><thead><tr><th>对照</th><th>说明</th></tr></thead><tbody><tr><td><a href="/pages/080502">平仓主流程</a></td><td>减少敞口；占用的是可平数量</td></tr><tr><td><a href="/pages/080503">强平与清算</a></td><td>标记价旁路，不是本同步链</td></tr><tr><td><a href="/pages/080505">保证金与资金协同</a></td><td>划转入金、加减保证金</td></tr><tr><td><a href="/pages/0803">交易规则</a></td><td>杠杆与开平语义</td></tr><tr><td>市价开仓 / 止盈止损触发开平</td><td>不展开为本文主路径</td></tr></tbody></table><p>同组：<a href="/pages/080502">平仓主流程</a> · <a href="/pages/0801">业务概述</a> · <a href="/pages/0802">系统架构</a> · <a href="/pages/080802">用户合约账户缓存</a></p>',23)])])}const m=e(n,[["render",i]]);export{c as __pageData,m as default};
